package org.viridexa.api.protection;
import java.net.*;import java.net.http.*;import java.sql.*;import java.util.*;import java.time.*;
import org.junit.jupiter.api.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.test.context.*;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.boot.json.JsonParserFactory;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Real MySQL account/security boundary, deterministic simulated Siteverify; never production facts. */
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class ProtectionMySqlIT {
 @org.springframework.beans.factory.annotation.Autowired org.springframework.jdbc.core.JdbcTemplate jdbc;
 @LocalServerPort int port; @MockitoBean TurnstileTransport siteverify;
 static String env(String n){return Objects.requireNonNull(System.getenv(n),n);}
 static final String QUOTA_DIR=quotaDirectory();static String quotaDirectory(){try{return java.nio.file.Files.createTempDirectory("viridexa-protection-it-").toString();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void configure(DynamicPropertyRegistry r){if(!env("GOVERNANCE_TEST_SCHEMA").startsWith("viridexa_governance_test_"))throw new IllegalStateException("Production forbidden");r.add("spring.datasource.url",()->env("GOVERNANCE_TEST_DB_URL"));r.add("spring.datasource.username",()->env("GOVERNANCE_TEST_RO"));r.add("spring.datasource.password",()->env("GOVERNANCE_TEST_PASSWORD"));r.add("spring.flyway.user",()->env("GOVERNANCE_TEST_MIGRATOR"));r.add("spring.flyway.password",()->env("GOVERNANCE_TEST_PASSWORD"));r.add("viridexa.review.username",()->env("GOVERNANCE_TEST_WRITER"));r.add("viridexa.review.password",()->env("GOVERNANCE_TEST_PASSWORD"));r.add("viridexa.accounts.username",()->env("GOVERNANCE_TEST_ACCOUNT"));r.add("viridexa.accounts.password",()->env("GOVERNANCE_TEST_PASSWORD"));r.add("viridexa.protected-root",()->env("VIRIDEXA_PROTECTED_ROOT"));r.add("viridexa.agent.runtime-directory",()->QUOTA_DIR);r.add("viridexa.agent.enabled",()->false);r.add("viridexa.agent.user-daily-requests",()->1);r.add("viridexa.turnstile.enabled",()->true);r.add("viridexa.turnstile.mode",()->"test");r.add("viridexa.turnstile.site-key",()->"1x00000000000000000000AA");r.add("viridexa.turnstile.secret",()->"1x0000000000000000000000000000000AA");r.add("viridexa.turnstile.hostnames",()->"example.com");}
 HttpClient client(){return HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).connectTimeout(Duration.ofSeconds(3)).build();}
 HttpResponse<String> request(HttpClient c,String path,String body,boolean csrf)throws Exception{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).timeout(Duration.ofSeconds(15));if(body==null)b.GET();else{b.header("Content-Type","application/json");if(csrf)b.header("X-CSRF-TOKEN",String.valueOf(JsonParserFactory.getJsonParser().parseMap(request(c,"/api/v1/csrf",null,false).body()).get("token")));b.POST(HttpRequest.BodyPublishers.ofString(body));}return c.send(b.build(),HttpResponse.BodyHandlers.ofString());}
 String unique(){return "protection-"+UUID.randomUUID()+"@example.invalid";}
 String registration(String email,String token){return "{\"email\":\""+email+"\",\"displayName\":\"Isolated security test\",\"password\":\"ISOLATED-test-only-2048\""+(token==null?"":",\"turnstileToken\":\""+token+"\"")+"}";}
 String login(String email,String password,String token){return "{\"email\":\""+email+"\",\"password\":\""+password+"\""+(token==null?"":",\"turnstileToken\":\""+token+"\"")+"}";}
 long count(String email)throws Exception{try(var c=DriverManager.getConnection(env("GOVERNANCE_TEST_DB_URL"),env("GOVERNANCE_TEST_MIGRATOR"),env("GOVERNANCE_TEST_PASSWORD"));var p=c.prepareStatement("SELECT COUNT(*) FROM app_user WHERE email=?")){p.setString(1,email);try(var rs=p.executeQuery()){rs.next();return rs.getLong(1);}}}
 @BeforeEach void provider()throws Exception{reset(siteverify);when(siteverify.verify(anyString(),anyString(),anyInt())).thenAnswer(i->Map.of("success",true,"hostname","example.com","action",i.<String>getArgument(1).startsWith("login-")?"login":"register","challenge_ts",Instant.now().toString()));}
 @Test void frontendBypassWithoutTokenCannotCreateAccount()throws Exception{String email=unique();var r=request(client(),"/api/v1/account/register",registration(email,null),true);assertEquals(403,r.statusCode());assertTrue(r.body().contains("CHALLENGE_REQUIRED"));assertEquals(0,count(email));verifyNoInteractions(siteverify);}
 @Test void validStrictEvidenceCreatesOnlyMemberAndReplayCannotCreateSecondAccount()throws Exception{var c=client();String email=unique(),token="register-"+UUID.randomUUID();assertEquals(201,request(c,"/api/v1/account/register",registration(email,token),true).statusCode());var session=request(c,"/api/v1/account/session",null,false);assertEquals(200,session.statusCode());assertTrue(session.body().contains("MEMBER"));assertFalse(session.body().contains("ADMIN"));assertEquals(403,request(c,"/api/v1/admin/session",null,false).statusCode());String other=unique();var replay=request(client(),"/api/v1/account/register",registration(other,token),true);assertEquals(403,replay.statusCode());assertTrue(replay.body().contains("CHALLENGE_REPLAY"));assertEquals(0,count(other));}
 @Test void providerOutageCannotCreateAccountAndMetadataHasNoSecret()throws Exception{doThrow(new java.net.http.HttpTimeoutException("DO_NOT_EXPOSE")).when(siteverify).verify(anyString(),anyString(),anyInt());String email=unique();var r=request(client(),"/api/v1/account/register",registration(email,"outage-"+UUID.randomUUID()),true);assertEquals(503,r.statusCode());assertEquals("10",r.headers().firstValue("Retry-After").orElse(""));assertFalse(r.body().contains("DO_NOT_EXPOSE"));assertEquals(0,count(email));var meta=request(client(),"/api/v1/security/meta",null,false);assertEquals(200,meta.statusCode());assertFalse(meta.body().contains("1x0000000000000000000000000000000AA"));assertTrue(meta.body().contains("\"turnstileMode\":\"test\""));}
 @Test void failedLoginProgressivelyRequiresChallengeAndCsrfStillApplies()throws Exception{String email=unique();assertEquals(201,request(client(),"/api/v1/account/register",registration(email,"register-"+UUID.randomUUID()),true).statusCode());var c=client();for(int i=0;i<3;i++)assertEquals(401,request(c,"/api/v1/account/login",login(email,"incorrect",null),true).statusCode());var challenge=request(c,"/api/v1/account/login",login(email,"ISOLATED-test-only-2048",null),true);assertEquals(403,challenge.statusCode());assertTrue(challenge.body().contains("CHALLENGE_REQUIRED"));assertEquals(403,request(c,"/api/v1/account/login",login(email,"ISOLATED-test-only-2048","login-"+UUID.randomUUID()),false).statusCode());assertEquals(200,request(c,"/api/v1/account/login",login(email,"ISOLATED-test-only-2048","login-"+UUID.randomUUID()),true).statusCode());}
 @Test void slowQueriesTimeOutAndConnectionRemainsUsable(){assertEquals(5,jdbc.getQueryTimeout());long began=System.nanoTime();assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.queryForObject("SELECT SLEEP(7)",Integer.class));assertTrue(Duration.ofNanos(System.nanoTime()-began).toSeconds()<10);assertEquals(1,jdbc.queryForObject("SELECT 1",Integer.class));}
 @Test void exhaustedAgentBudgetReturns429WhileNormalCatalogRemainsAvailable()throws Exception{var c=client();String email=unique();assertEquals(201,request(c,"/api/v1/account/register",registration(email,"register-"+UUID.randomUUID()),true).statusCode());var first=request(c,"/api/v1/agent/runs","{\"question\":\"What sources are available?\"}",true);assertEquals(202,first.statusCode(),first.body());String id=String.valueOf(JsonParserFactory.getJsonParser().parseMap(first.body()).get("id"));long deadline=System.nanoTime()+Duration.ofSeconds(10).toNanos();while(System.nanoTime()<deadline){var run=JsonParserFactory.getJsonParser().parseMap(request(c,"/api/v1/agent/runs/"+id,null,false).body());if(!Set.of("QUEUED","RUNNING").contains(run.get("status")))break;Thread.sleep(100);}var second=request(c,"/api/v1/agent/runs","{\"question\":\"Another source question\"}",true);assertEquals(429,second.statusCode(),second.body());assertTrue(second.headers().firstValue("Retry-After").isPresent());assertEquals(200,request(c,"/api/v1/plants",null,false).statusCode());}
 @Test void documentationIsNotPublicAndReadonlyCatalogSurvivesVerifierFailure()throws Exception{var c=client();assertEquals(401,request(c,"/api-docs",null,false).statusCode());assertEquals(401,request(c,"/actuator/env",null,false).statusCode());assertEquals(200,request(c,"/api/v1/plants",null,false).statusCode());assertEquals(200,request(c,"/api/v1/graph/meta",null,false).statusCode());assertEquals(401,request(c,"/api/v1/agent/runs/00000000-0000-0000-0000-000000000000",null,false).statusCode());}
}
